<?php
declare(strict_types=1);
session_start();
$DB_HOST = 'localhost';
$DB_NAME = 'broken_link_checker';
$DB_USER = 'root';
$DB_PASS = '';
try {
    $pdo = new PDO("mysql:host={$DB_HOST};dbname={$DB_NAME};charset=utf8mb4", $DB_USER, $DB_PASS, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false,
    ]);
} catch (PDOException $e) {
    http_response_code(500);
    exit('Lỗi MySQL: ' . $e->getMessage());
}
function e($value): string { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function redirect(string $url): never { header('Location: '.$url); exit; }
function flash(string $message, string $type='success'): void { $_SESSION['flash']=['message'=>$message,'type'=>$type]; }
function show_flash(): void {
    if (!empty($_SESSION['flash'])) { $f=$_SESSION['flash']; unset($_SESSION['flash']);
        echo '<div class="alert alert-'.e($f['type']).' alert-dismissible fade show" role="alert">'.e($f['message']).'<button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Đóng"></button></div>'; }
}
function current_user(): ?array { return isset($_SESSION['user']) && is_array($_SESSION['user']) ? $_SESSION['user'] : null; }
function require_login(): void { if (!current_user()) { redirect('login.php'); } }
function require_admin(): void { if (defined('LINKSCOPE_WORKER') && LINKSCOPE_WORKER === true) return; require_login(); if ((current_user()['role'] ?? '') !== 'admin') { http_response_code(403); exit('Bạn không có quyền thực hiện chức năng này.'); } }
function csrf_token(): string { if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32)); return $_SESSION['csrf_token']; }
function verify_csrf(): void { if (defined('LINKSCOPE_WORKER') && LINKSCOPE_WORKER === true) return; if ($_SERVER['REQUEST_METHOD'] === 'POST' && !hash_equals((string)($_SESSION['csrf_token'] ?? ''), (string)($_POST['csrf_token'] ?? ''))) { http_response_code(403); exit('CSRF token không hợp lệ. Hãy tải lại trang và thử lại.'); } }
